import { school, menu, rolePermissions } from './data.js';
import { store } from './store.js';
import { icon, escapeHtml, initials, dateLabel, badge, modal, toast, pageHead, dataDemo } from './ui.js';

const ui = {
  sidebarOpen: false,
  modal: null,
  filters: {},
  pages: {},
  public: { step: 1, fields: {}, submitted: null, statusQuery: '', statusResult: null }
};

const app = document.querySelector('#app');
const live = document.querySelector('#live-region');
const stateFor = key => ui.filters[key] || {};
const pageFor = key => ui.pages[key] || 1;
const setPage = (key, value) => { ui.pages[key] = value; };
const routeKey = () => (location.hash.replace(/^#\/?/, '') || 'dashboard').split('/')[0];
const isPublic = () => ['register', 'check-status'].includes(routeKey());
const go = key => { location.hash = `#/${key}`; };
const today = '2026-06-24';

function announce(text) { if (live) live.textContent = text; }
function queryFor(key) { return stateFor(key).query || ''; }
function initialsCell(name, secondary = '') { return `<div class="person-cell"><span class="list-avatar">${initials(name)}</span><div><strong>${escapeHtml(name)}</strong><small>${escapeHtml(secondary)}</small></div></div>`; }
function activeMenu(key) { return menu.some(group => group.items.some(item => item.key === key)); }
function formatCount(n) { return new Intl.NumberFormat('id-ID').format(n); }
function matchesQuery(item, query, fields) { if (!query) return true; const q = query.toLowerCase(); return fields.some(field => String(item[field] || '').toLowerCase().includes(q)); }
function paginate(items, key, size = 6) { const total = Math.max(1, Math.ceil(items.length / size)); let page = Math.min(pageFor(key), total); setPage(key, page); return { items: items.slice((page - 1) * size, page * size), page, total, count: items.length, from: items.length ? (page - 1) * size + 1 : 0, to: Math.min(page * size, items.length) }; }
function pagination(key, result) { if (result.total <= 1) return ''; return `<div class="pagination"><span>Menampilkan ${result.from}–${result.to} dari ${result.count} data tersaring</span><div class="page-buttons"><button class="page-btn" data-action="page" data-page-key="${key}" data-page="${result.page - 1}" ${result.page <= 1 ? 'disabled' : ''}>${icon('left',13)}</button>${Array.from({ length: result.total }, (_, i) => `<button class="page-btn ${i + 1 === result.page ? 'current' : ''}" data-action="page" data-page-key="${key}" data-page="${i + 1}">${i + 1}</button>`).join('')}<button class="page-btn" data-action="page" data-page-key="${key}" data-page="${result.page + 1}" ${result.page >= result.total ? 'disabled' : ''}>${icon('right',13)}</button></div></div>`; }
function actionButtons(entity, id, view = true) { return `<div class="table-actions">${view ? `<button class="table-icon" data-action="view-${entity}" data-id="${id}" title="Lihat detail">${icon('eye',14)}</button>` : ''}<button class="table-icon" data-action="edit-${entity}" data-id="${id}" title="Edit">${icon('edit',14)}</button><button class="table-icon" data-action="delete-${entity}" data-id="${id}" title="Hapus">${icon('trash',14)}</button></div>`; }
function statusOptions(values, selected = '') { return values.map(value => `<option value="${escapeHtml(value)}" ${selected === value ? 'selected' : ''}>${escapeHtml(value)}</option>`).join(''); }
function modalFormField(label, name, value = '', required = true, type = 'text', extra = '') { return `<div class="field ${extra}"><label>${label}${required ? ' <em>*</em>' : ''}</label><input class="form-control" name="${name}" type="${type}" value="${escapeHtml(value)}" ${required ? 'required' : ''} /></div>`; }

function sidebarHtml() {
  return `<aside class="sidebar ${ui.sidebarOpen ? 'open' : ''}"><div class="brand"><span class="brand-mark">${icon('book',21)}</span><span class="brand-copy"><span class="brand-name">SekolahMu</span><span class="brand-sub">Academic workspace</span></span></div><nav>${menu.map(group => `<div class="nav-section">${group.section}</div>${group.items.map(item => `<button class="nav-item ${routeKey() === item.key ? 'active' : ''}" data-action="navigate" data-route="${item.key}"><span class="nav-icon">${icon(item.icon,15)}</span><span>${item.label}</span></button>`).join('')}`).join('')}</nav><div class="sidebar-footer"><div class="demo-note"><strong>Mode prototype</strong>Data tersimpan lokal di browser. Belum ada database produksi.</div></div></aside>`;
}
function topbarHtml() { return `<header class="topbar"><button class="menu-toggle" data-action="toggle-sidebar" aria-label="Buka menu">${icon('menu',18)}</button><div class="top-search"><span class="search-icon">${icon('search',14)}</span><input data-top-search placeholder="Cari modul, nama, atau nomor pendaftaran" value="${escapeHtml(ui.topQuery || '')}" aria-label="Pencarian cepat" /></div><div class="top-actions"><button class="icon-button" data-action="show-notification" aria-label="Notifikasi">${icon('bell',17)}<span class="dot"></span></button><div class="profile"><span class="avatar">AS</span><span class="profile-copy"><span class="profile-name">Andi Setiawan</span><span class="profile-role">Administrator sekolah</span></span>${icon('right',13)}</div></div></header>`; }
function adminShell(content) { return `<div class="app-shell">${sidebarHtml()}${ui.sidebarOpen ? '<div class="sidebar-overlay" data-action="toggle-sidebar"></div>' : ''}<div class="workspace">${topbarHtml()}<main class="main">${content}</main></div>${ui.modal ? ui.modal.html : ''}<div class="toast-stack"></div></div>`; }

function dashboardPage() {
  const state = store.get();
  const activeStudents = state.students.filter(s => s.status === 'Aktif').length;
  const activeTeachers = state.teachers.filter(t => t.status === 'Aktif').length;
  const todayRecords = Object.entries(state.attendance).filter(([key]) => key.startsWith(today));
  const att = todayRecords.flatMap(([, records]) => Object.values(records));
  const attendance = { Hadir: att.filter(x => x === 'Hadir').length, Izin: att.filter(x => x === 'Izin').length, Sakit: att.filter(x => x === 'Sakit').length, Alpa: att.filter(x => x === 'Alpa').length };
  const totalAtt = Object.values(attendance).reduce((a,b) => a + b, 0) || 1;
  const rate = Math.round(attendance.Hadir / totalAtt * 100);
  const statusCounts = statusSummary();
  const monthBars = [['Jan',54],['Feb',72],['Mar',68],['Apr',86],['Mei',104],['Jun',92]];
  const actions = `<button class="btn" data-action="navigate" data-route="register">${icon('arrow',14)} Lihat halaman publik</button><button class="btn btn-primary" data-action="navigate" data-route="applicants">${icon('clipboard',14)} Tinjau pendaftar</button>`;
  return `${pageHead('Ringkasan · 24 Juni 2026', 'Pantau sekolah tanpa kehilangan konteks.', `Selamat pagi, Andi. Berikut ringkasan operasional ${school.shortName} hari ini.`, actions)}<div style="display:flex;justify-content:flex-end;margin-top:-11px;margin-bottom:14px">${dataDemo()}</div><div class="insight-grid"><div class="card insight"><div class="insight-top"><span>Murid aktif</span><span class="insight-icon">${icon('users',14)}</span></div><div class="insight-value">${formatCount(activeStudents)}</div><div class="insight-foot"><span class="trend-up">↑ 3,2%</span> dibanding semester lalu</div></div><div class="card insight"><div class="insight-top"><span>Guru aktif</span><span class="insight-icon">${icon('teacher',14)}</span></div><div class="insight-value">${formatCount(activeTeachers)}</div><div class="insight-foot"><span class="trend-neutral">${state.teachers.filter(t => t.status === 'Cuti').length} guru</span> sedang cuti</div></div><div class="card insight"><div class="insight-top"><span>Total kelas</span><span class="insight-icon">${icon('book',14)}</span></div><div class="insight-value">${state.classes.length}</div><div class="insight-foot"><span class="trend-neutral">Tahun ajaran</span> 2026/2027</div></div><div class="card insight"><div class="insight-top"><span>Pendaftar baru</span><span class="insight-icon">${icon('spark',14)}</span></div><div class="insight-value">${statusCounts['Menunggu Verifikasi']}</div><div class="insight-foot"><span class="trend-up">↑ 12%</span> dari minggu lalu</div></div></div><div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Tren pendaftaran SPMB</h2><p class="card-subtitle">Jumlah pendaftar masuk · Januari–Juni 2026</p></div><button class="btn btn-sm" data-action="navigate" data-route="spmb">Buka dashboard ${icon('arrow',12)}</button></div><div class="chart-body"><div class="bar-chart">${monthBars.map((item, i) => `<div class="bar-col"><div class="bar ${i === monthBars.length - 1 ? 'current' : ''}" style="height:${item[1] / 120 * 100}%" title="${item[1]} pendaftar"></div><span class="bar-label">${item[0]}</span></div>`).join('')}</div><div class="chart-legend"><span><i class="legend-dot"></i>Bulan berjalan</span><span><i class="legend-dot soft"></i>Periode sebelumnya</span><span style="margin-left:auto">Total periode: <strong>${formatCount(state.applicants.length)}</strong></span></div></div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Kehadiran hari ini</h2><p class="card-subtitle">Rekap seluruh kelas · 24 Juni 2026</p></div><button class="btn btn-sm" data-action="navigate" data-route="attendance">Kelola</button></div><div class="att-summary"><div class="ring-wrap"><div class="ring"><div class="ring-center"><strong>${rate}%</strong><span>Hadir</span></div></div><div><div class="section-label">Status tercatat</div><strong style="font-size:19px">${formatCount(att.length)} <span style="font-size:11px;color:var(--muted);font-weight:500">murid</span></strong><p style="font-size:10px;color:var(--muted);margin:3px 0 0">${todayRecords.length} dari ${state.classes.length} kelas diperbarui</p></div></div><div class="metric-list">${[['Hadir','green',attendance.Hadir],['Izin','amber',attendance.Izin],['Sakit','purple',attendance.Sakit],['Alpa','red',attendance.Alpa]].map(([label,color,num]) => `<div class="metric-row"><span class="metric-label">${label}</span><span class="metric-bar"><i class="metric-fill fill-${color}" style="width:${Math.max(2, num / totalAtt * 100)}%"></i></span><strong class="metric-count">${num}</strong></div>`).join('')}</div></div></section></div><div class="lower-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Pendaftar terbaru</h2><p class="card-subtitle">5 data terakhir yang masuk ke sistem</p></div><button class="btn btn-ghost btn-sm" data-action="navigate" data-route="applicants">Lihat semua ${icon('arrow',12)}</button></div><div class="list">${state.applicants.slice(0,5).map(a => `<div class="list-row"><span class="list-avatar">${initials(a.name)}</span><div class="list-main"><strong>${escapeHtml(a.name)}</strong><span>${escapeHtml(a.id)} · ${escapeHtml(a.path)}</span></div><div class="list-side">${badge(a.status)}<br><span style="display:inline-block;margin-top:4px">${dateLabel(a.date)}</span></div></div>`).join('')}</div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Akses cepat</h2><p class="card-subtitle">Lanjutkan pekerjaan utama</p></div></div><div class="quick-grid"><button class="quick" data-action="navigate" data-route="students"><strong>${icon('users',13)} Data murid</strong><span>Tambah atau perbarui profil</span></button><button class="quick" data-action="navigate" data-route="attendance"><strong>${icon('calendar',13)} Isi absensi</strong><span>Rekap kelas hari ini</span></button><button class="quick" data-action="navigate" data-route="tasks"><strong>${icon('file',13)} Kelola tugas</strong><span>Atur tenggat & prioritas</span></button><button class="quick" data-action="navigate" data-route="verification"><strong>${icon('shield',13)} Verifikasi SPMB</strong><span>${statusCounts['Menunggu Verifikasi']} menunggu review</span></button></div></section></div>`;
}
function statusSummary() { return store.get().applicants.reduce((acc, item) => { acc[item.status] = (acc[item.status] || 0) + 1; return acc; }, { 'Menunggu Verifikasi': 0, 'Sedang Diverifikasi': 0, 'Terverifikasi': 0, 'Diterima': 0, 'Ditolak': 0 }); }

function activitiesPage() { const items = store.get().activities; return `${pageHead('Dashboard · Aktivitas terbaru', 'Jejak aktivitas administrasi', 'Perubahan penting dari seluruh modul demo, diurutkan dari yang terbaru.', `<button class="btn" data-action="reset-demo">${icon('refresh',14)} Reset data demo</button>`)}<div class="card"><div class="card-head"><div><h2 class="card-title">Aktivitas terbaru</h2><p class="card-subtitle">Data lokal prototype · ${items.length} aktivitas tersimpan</p></div>${dataDemo()}</div><div class="timeline">${items.map(item => `<div class="timeline-item"><span class="timeline-dot"></span><div class="timeline-copy"><strong>${escapeHtml(item.title)}</strong><p>${escapeHtml(item.copy)}</p><span style="font-size:9px;color:#9aa6bf">${escapeHtml(item.time)}</span></div></div>`).join('')}</div></div>`; }

function tableToolbar(key, placeholder, extra = '') { return `<div class="table-toolbar"><div class="toolbar-search"><span>${icon('search',14)}</span><input data-table-search="${key}" placeholder="${placeholder}" value="${escapeHtml(queryFor(key))}" /></div>${extra}</div>`; }
function studentsPage() { const state = store.get(), filter = stateFor('students'); let rows = state.students.filter(s => matchesQuery(s, filter.query, ['name','id','className'])).filter(s => !filter.status || s.status === filter.status); const result = paginate(rows, 'students'); return `${pageHead('Akademik · Data murid', 'Data murid', 'Kelola profil murid dan penempatan kelas dalam satu ruang kerja.', `<button class="btn btn-primary" data-action="new-student">${icon('plus',14)} Tambah murid</button>`)}<div class="card table-card">${tableToolbar('students','Cari nama, nomor induk, atau kelas', `<select class="select-control" data-filter-select="students.status"><option value="">Semua status</option>${statusOptions(['Aktif','Nonaktif'], filter.status)}</select>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Murid</th><th>Nomor induk</th><th>Kelas</th><th>Jenis kelamin</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${result.items.length ? result.items.map(s => `<tr><td>${initialsCell(s.name, s.phone)}</td><td class="mono">${s.id}</td><td>${escapeHtml(s.className)}</td><td>${escapeHtml(s.gender)}</td><td>${badge(s.status)}</td><td>${actionButtons('student', s.id)}</td></tr>`).join('') : emptyRow(6, 'Murid tidak ditemukan', 'Coba ubah kata kunci atau filter status.')}</tbody></table></div>${pagination('students', result)}</div>`; }
function teachersPage() { const state = store.get(), filter = stateFor('teachers'); let rows = state.teachers.filter(t => matchesQuery(t, filter.query, ['name','id','subject','classes'])).filter(t => !filter.status || t.status === filter.status); const result = paginate(rows, 'teachers'); return `${pageHead('Akademik · Data guru', 'Data guru', 'Direktori guru, mata pelajaran, dan kelas yang diampu.', `<button class="btn btn-primary" data-action="new-teacher">${icon('plus',14)} Tambah guru</button>`)}<div class="card table-card">${tableToolbar('teachers','Cari nama, ID internal, atau mata pelajaran', `<select class="select-control" data-filter-select="teachers.status"><option value="">Semua status</option>${statusOptions(['Aktif','Cuti'], filter.status)}</select>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Guru</th><th>ID internal</th><th>Mata pelajaran</th><th>Kelas diampu</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${result.items.length ? result.items.map(t => `<tr><td>${initialsCell(t.name, t.email)}</td><td class="mono">${t.id}</td><td>${escapeHtml(t.subject)}</td><td>${escapeHtml(t.classes)}</td><td>${badge(t.status)}</td><td>${actionButtons('teacher', t.id)}</td></tr>`).join('') : emptyRow(6, 'Guru tidak ditemukan', 'Coba ubah kata kunci atau filter status.')}</tbody></table></div>${pagination('teachers', result)}</div>`; }
function classesPage() { const state = store.get(), filter = stateFor('classes'); let rows = state.classes.filter(c => matchesQuery(c, filter.query, ['name','level','homeroom'])); const result = paginate(rows, 'classes'); return `${pageHead('Akademik · Struktur kelas', 'Kelas', 'Pantau wali kelas, kapasitas, dan jumlah murid aktual per rombel.', `<button class="btn btn-primary" data-action="new-class">${icon('plus',14)} Tambah kelas</button>`)}<div class="card table-card">${tableToolbar('classes','Cari nama kelas atau wali kelas')}<div class="table-wrap"><table class="data-table"><thead><tr><th>Kelas</th><th>Tingkat</th><th>Wali kelas</th><th>Jumlah murid</th><th>Kapasitas</th><th>Aksi</th></tr></thead><tbody>${result.items.length ? result.items.map(c => { const count = state.students.filter(s => s.className === c.name).length; return `<tr><td><strong>${escapeHtml(c.name)}</strong><small style="display:block;color:var(--muted);font-size:9px;margin-top:2px">${c.id}</small></td><td>${escapeHtml(c.level)}</td><td>${escapeHtml(c.homeroom)}</td><td><strong>${count}</strong> murid</td><td><span class="mono">${count}/${c.capacity}</span></td><td>${actionButtons('class', c.id, false)}</td></tr>`; }).join('') : emptyRow(6, 'Kelas tidak ditemukan', 'Coba ubah kata kunci.')}</tbody></table></div>${pagination('classes', result)}</div>`; }
function emptyRow(colspan, title, copyText) { return `<tr><td colspan="${colspan}"><div class="empty-state"><div class="empty-icon">${icon('search',18)}</div><strong>${title}</strong><span>${copyText}</span></div></td></tr>`; }

function attendancePage() { const state = store.get(), filter = stateFor('attendance'); const className = filter.className || state.classes[0].name; const date = filter.date || today; const classStudents = state.students.filter(s => s.className === className); const draft = ui.attDraft || store.getAttendance(date, className); const counts = ['Hadir','Izin','Sakit','Alpa'].reduce((acc, k) => { acc[k] = classStudents.filter(s => (draft[s.id] || 'Hadir') === k).length; return acc; }, {}); const dirty = ui.attDirty; return `${pageHead('Akademik · Kehadiran', 'Absensi murid', 'Catat kehadiran kelas, tinjau rekap, lalu simpan perubahan demo.', `<button class="btn" data-action="export-attendance">${icon('download',14)} Ekspor CSV</button><button class="btn btn-primary" data-action="save-attendance" ${dirty ? '' : 'disabled'}>${icon('check',14)} Simpan absensi</button>`)}<div class="detail-banner"><div><strong>${escapeHtml(className)} · ${dateLabel(date)}</strong><span>Pilih status per murid. Data belum tersimpan sampai tombol Simpan ditekan.</span></div><div class="head-actions"><select class="select-control" data-filter-select="attendance.className">${state.classes.map(c => `<option ${c.name === className ? 'selected' : ''}>${escapeHtml(c.name)}</option>`).join('')}</select><input class="form-control" style="width:140px" type="date" data-filter-input="attendance.date" value="${date}" /></div></div><div class="insight-grid"><div class="card insight"><div class="insight-top"><span>Hadir</span><span class="insight-icon">${icon('check',14)}</span></div><div class="insight-value">${counts.Hadir}</div><div class="insight-foot">${classStudents.length ? Math.round(counts.Hadir/classStudents.length*100) : 0}% dari kelas</div></div><div class="card insight"><div class="insight-top"><span>Izin</span><span class="insight-icon">${icon('info',14)}</span></div><div class="insight-value">${counts.Izin}</div><div class="insight-foot">Perlu tindak lanjut wali</div></div><div class="card insight"><div class="insight-top"><span>Sakit</span><span class="insight-icon">${icon('pulse',14)}</span></div><div class="insight-value">${counts.Sakit}</div><div class="insight-foot">Dokumen opsional</div></div><div class="card insight"><div class="insight-top"><span>Alpa</span><span class="insight-icon">${icon('close',14)}</span></div><div class="insight-value">${counts.Alpa}</div><div class="insight-foot">Segera konfirmasi</div></div></div><div class="card table-card"><div class="table-toolbar"><strong style="font-size:12px">Daftar kehadiran ${escapeHtml(className)}</strong><button class="btn btn-sm" style="margin-left:auto" data-action="mark-all-present">${icon('check',12)} Tandai semua hadir</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Murid</th><th>Nomor induk</th><th>Status kehadiran</th><th>Catatan</th></tr></thead><tbody>${classStudents.map(s => `<tr><td>${initialsCell(s.name, s.gender)}</td><td class="mono">${s.id}</td><td><select class="select-control" style="width:145px" data-att-status="${s.id}">${statusOptions(['Hadir','Izin','Sakit','Alpa'], draft[s.id] || 'Hadir')}</select></td><td><span style="font-size:10px;color:var(--muted)">${(draft[s.id] || 'Hadir') === 'Hadir' ? 'Tercatat hadir' : 'Perlu keterangan jika disimpan'}</span></td></tr>`).join('')}</tbody></table></div></div>`; }
function tasksPage() { const state = store.get(), filter = stateFor('tasks'); let rows = state.tasks.filter(t => matchesQuery(t, filter.query, ['title','className','teacher'])).filter(t => !filter.priority || t.priority === filter.priority).filter(t => !filter.className || t.className === filter.className); const result = paginate(rows, 'tasks'); return `${pageHead('Akademik · Penugasan', 'Tugas', 'Atur tugas, tenggat, dan prioritas pembelajaran tanpa mengklaim pengumpulan jawaban.', `<button class="btn btn-primary" data-action="new-task">${icon('plus',14)} Buat tugas</button>`)}<div class="card table-card">${tableToolbar('tasks','Cari judul tugas atau guru', `<select class="select-control" data-filter-select="tasks.className"><option value="">Semua kelas</option>${state.classes.map(c => `<option value="${escapeHtml(c.name)}" ${filter.className === c.name ? 'selected' : ''}>${escapeHtml(c.name)}</option>`).join('')}</select><select class="select-control" data-filter-select="tasks.priority"><option value="">Semua prioritas</option>${statusOptions(['Rendah','Normal','Tinggi'], filter.priority)}</select>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Judul tugas</th><th>Kelas</th><th>Guru pembuat</th><th>Tenggat</th><th>Prioritas</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${result.items.length ? result.items.map(t => { const due = new Date(`${t.due}T00:00:00`); const diff = Math.ceil((due - new Date('2026-06-24T00:00:00')) / 86400000); const dueClass = diff < 0 ? 'color:var(--red)' : diff <= 3 ? 'color:var(--amber)' : ''; return `<tr><td>${initialsCell(t.title, t.description)}</td><td>${escapeHtml(t.className)}</td><td>${escapeHtml(t.teacher)}</td><td><span style="${dueClass};font-weight:700">${dateLabel(t.due)}</span><small style="display:block;color:var(--muted);font-size:9px">${diff < 0 ? 'Terlambat' : diff <= 3 ? 'Segera jatuh tempo' : `${diff} hari lagi`}</small></td><td>${badge(t.priority)}</td><td>${badge(t.status)}</td><td>${actionButtons('task', t.id)}</td></tr>`; }).join('') : emptyRow(7, 'Tugas tidak ditemukan', 'Coba ubah kata kunci atau filter.')}</tbody></table></div>${pagination('tasks', result)}</div>`; }

function spmbCards() { const c = statusSummary(); return `<div class="insight-grid"><div class="card insight"><div class="insight-top"><span>Total pendaftar</span><span class="insight-icon">${icon('clipboard',14)}</span></div><div class="insight-value">${formatCount(Object.values(c).reduce((a,b)=>a+b,0))}</div><div class="insight-foot">Periode 1 Jun–31 Jul 2026</div></div><div class="card insight"><div class="insight-top"><span>Menunggu verifikasi</span><span class="insight-icon">${icon('shield',14)}</span></div><div class="insight-value">${c['Menunggu Verifikasi']}</div><div class="insight-foot">Perlu ditinjau petugas</div></div><div class="card insight"><div class="insight-top"><span>Terverifikasi</span><span class="insight-icon">${icon('check',14)}</span></div><div class="insight-value">${c.Terverifikasi}</div><div class="insight-foot">Siap masuk seleksi</div></div><div class="card insight"><div class="insight-top"><span>Diterima</span><span class="insight-icon">${icon('spark',14)}</span></div><div class="insight-value">${c.Diterima}</div><div class="insight-foot">Hasil seleksi tahap 1</div></div></div>`; }
function spmbPage() { const state = store.get(), c = statusSummary(); const paths = ['Zonasi','Prestasi','Afirmasi']; return `${pageHead('SPMB · Tahun ajaran 2026/2027', 'Penerimaan murid baru', 'Satu tempat untuk membaca arus pendaftar dan menjaga proses verifikasi tetap tertata.', `<button class="btn" data-action="navigate" data-route="register">${icon('arrow',14)} Formulir publik</button><button class="btn btn-primary" data-action="navigate" data-route="applicants">Kelola pendaftar</button>`)}${spmbCards()}<div class="dashboard-grid"><section class="card"><div class="card-head"><div><h2 class="card-title">Pendaftar berdasarkan jalur</h2><p class="card-subtitle">Distribusi dari ${state.applicants.length} data demo</p></div><span class="data-demo">Periode aktif</span></div><div class="chart-body">${paths.map((path, i) => { const count = state.applicants.filter(a => a.path === path).length; return `<div style="display:flex;align-items:center;gap:13px;margin:18px 0"><span style="width:72px;font-size:11px;color:var(--muted)">${path}</span><span class="metric-bar" style="height:10px"><i class="metric-fill ${i === 0 ? 'fill-green' : i === 1 ? 'fill-blue' : 'fill-amber'}" style="width:${Math.max(7,count/state.applicants.length*100)}%;background:${i===0?'#5dbca2':i===1?'#7899f8':'#f5b64f'}"></i></span><strong style="font-size:12px">${count}</strong></div>`; }).join('')}<div class="notice" style="margin-top:22px;margin-bottom:0">${icon('info',14)} Jalur dan tanggal di atas adalah data sintetis untuk menguji alur. Belum ada proses seleksi server.</div></div></section><section class="card"><div class="card-head"><div><h2 class="card-title">Alur status</h2><p class="card-subtitle">Tahapan yang digunakan petugas</p></div></div><div style="padding:17px 20px">${['Menunggu Verifikasi','Sedang Diverifikasi','Terverifikasi','Diterima / Ditolak'].map((s,i)=>`<div style="display:flex;gap:12px;position:relative;padding-bottom:${i<3?'22px':'0'}"><span style="width:24px;height:24px;border-radius:8px;background:${i<3?'var(--blue-2)':'var(--green-bg)'};color:${i<3?'var(--blue)':'var(--green)'};display:grid;place-items:center;font-size:10px;font-weight:800;z-index:1">${i+1}</span>${i<3?'<i style="position:absolute;left:11px;top:24px;height:22px;border-left:1px dashed #cdd7ec"></i>':''}<span style="font-size:11px;padding-top:3px">${s}</span></div>`).join('')}</div></section></div><div class="card"><div class="card-head"><div><h2 class="card-title">Pendaftar terbaru</h2><p class="card-subtitle">Pantau data yang perlu ditindaklanjuti</p></div><button class="btn btn-ghost btn-sm" data-action="navigate" data-route="verification">Buka verifikasi ${icon('arrow',12)}</button></div><div class="list">${state.applicants.slice(0,4).map(a=>`<div class="list-row"><span class="list-avatar">${initials(a.name)}</span><div class="list-main"><strong>${escapeHtml(a.name)}</strong><span>${a.id} · ${a.school}</span></div><div class="list-side">${badge(a.status)}</div></div>`).join('')}</div></div>`; }
function applicantsPage(mode = 'all') { const state = store.get(), filter = stateFor('applicants'); let rows = state.applicants.filter(a => matchesQuery(a, filter.query, ['name','id','school'])).filter(a => !filter.status || a.status === filter.status).filter(a => !filter.path || a.path === filter.path); if (mode === 'pending') rows = rows.filter(a => ['Menunggu Verifikasi','Sedang Diverifikasi'].includes(a.status)); const result = paginate(rows, `applicants-${mode}`); return `${pageHead(mode === 'pending' ? 'SPMB · Pemeriksaan dokumen' : 'SPMB · Database pendaftar', mode === 'pending' ? 'Verifikasi berkas' : 'Data pendaftar', mode === 'pending' ? 'Prioritaskan data yang menunggu pemeriksaan dan simpan status secara eksplisit.' : 'Cari, filter, dan buka detail setiap pendaftar sintetis.', `<button class="btn" data-action="navigate" data-route="spmb">${icon('left',14)} Ringkasan SPMB</button><button class="btn btn-primary" data-action="navigate" data-route="register">${icon('plus',14)} Simulasi pendaftaran</button>`)}<div class="card table-card">${tableToolbar(`applicants`, 'Cari nama atau nomor pendaftaran', `<select class="select-control" data-filter-select="applicants.status"><option value="">Semua status</option>${statusOptions(['Menunggu Verifikasi','Sedang Diverifikasi','Terverifikasi','Diterima','Ditolak'], filter.status)}</select><select class="select-control" data-filter-select="applicants.path"><option value="">Semua jalur</option>${statusOptions(['Zonasi','Prestasi','Afirmasi'], filter.path)}</select>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Nomor / pendaftar</th><th>Asal sekolah</th><th>Jalur</th><th>Tanggal</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${result.items.length ? result.items.map(a => `<tr><td>${initialsCell(a.name, a.id)}</td><td>${escapeHtml(a.school)}</td><td>${escapeHtml(a.path)}</td><td>${dateLabel(a.date)}</td><td>${badge(a.status)}</td><td>${actionButtons('applicant', a.id, true)}</td></tr>`).join('') : emptyRow(6, 'Pendaftar tidak ditemukan', 'Belum ada data yang sesuai filter.')}</tbody></table></div>${pagination(`applicants-${mode}`, result)}</div>`; }
function statusLookupAdmin() { const result = ui.adminStatusResult; return `${pageHead('SPMB · Pelacakan', 'Status pendaftaran', 'Cari nomor pendaftaran demo untuk melihat status terkini tanpa membuka seluruh tabel.', `<button class="btn" data-action="navigate" data-route="applicants">${icon('left',14)} Kembali ke pendaftar</button>`)}<div class="card card-pad" style="max-width:760px"><form data-form="admin-status"><div class="field"><label>Nomor pendaftaran</label><input class="form-control" name="number" placeholder="Contoh: SPMB-26041" value="${escapeHtml(ui.adminStatusQuery || '')}" required /></div><div class="form-actions"><button class="btn btn-primary">${icon('search',14)} Periksa status</button></div></form>${result ? `<div style="margin-top:22px;padding-top:18px;border-top:1px solid var(--line)"><div class="detail-banner"><div><strong>${escapeHtml(result.name)}</strong><span>${result.id} · ${result.school}</span></div>${badge(result.status)}</div><div class="detail-list"><div class="detail-item"><label>Jalur pendaftaran</label><strong>${result.path}</strong></div><div class="detail-item"><label>Tanggal masuk</label><strong>${dateLabel(result.date)}</strong></div></div></div>` : ''}</div>`; }

function usersPage() { const state = store.get(), filter = stateFor('users'); const rows = state.users.filter(u => matchesQuery(u, filter.query, ['name','email','role'])).filter(u => !filter.role || u.role === filter.role); const result = paginate(rows, 'users'); return `${pageHead('Administrasi · Akses akun', 'Manajemen pengguna', 'Kelola daftar akun demo dan peran yang sedang digunakan di lingkungan sekolah.', `${dataDemo()}`)}<div class="card table-card">${tableToolbar('users','Cari nama, email, atau peran', `<select class="select-control" data-filter-select="users.role"><option value="">Semua peran</option>${statusOptions(['Admin','Guru','Murid','Petugas SPMB'], filter.role)}</select>`)}<div class="table-wrap"><table class="data-table"><thead><tr><th>Pengguna</th><th>Email demo</th><th>Peran</th><th>Status akun</th><th>Aktivitas terakhir</th></tr></thead><tbody>${result.items.map(u => `<tr><td>${initialsCell(u.name, u.id)}</td><td>${escapeHtml(u.email)}</td><td>${badge(u.role)}</td><td>${badge(u.status)}</td><td style="color:var(--muted)">${escapeHtml(u.lastActive)}</td></tr>`).join('')}</tbody></table></div>${pagination('users', result)}</div>`; }
function rolesPage() { return `${pageHead('Administrasi · Kontrol akses', 'Hak akses', 'Matriks akses ini hanya representasi UI. Otorisasi sebenarnya wajib diterapkan pada backend Laravel.', `<span class="data-demo">Catatan keamanan backend</span>`)}<div class="card table-card"><div class="card-head"><div><h2 class="card-title">Matriks peran dan modul</h2><p class="card-subtitle">Terakhir diperbarui pada prototype · 24 Juni 2026</p></div></div><div class="table-wrap"><table class="permission-table"><thead><tr><th>Modul</th><th>Admin</th><th>Guru</th><th>Murid</th><th>Petugas SPMB</th></tr></thead><tbody>${rolePermissions.map(row => `<tr><td><strong>${row.module}</strong></td>${['Admin','Guru','Murid','Petugas SPMB'].map(role => `<td>${row[role] === true ? '<span class="checkmark">✓ Kelola</span>' : row[role] === false ? '<span class="dash">—</span>' : `<span style="color:var(--muted)">${row[role]}</span>`}</td>`).join('')}</tr>`).join('')}</tbody></table></div></div><div class="notice" style="margin-top:15px">${icon('shield',14)} Menyembunyikan tombol di frontend bukan mekanisme keamanan. Validasi role, policy, dan akses data perlu ditegakkan di backend.</div>`; }
function placeholderPage(title, desc, label) { return `${pageHead('Administrasi', title, desc)}<div class="card placeholder"><div class="empty-icon">${icon(title === 'Laporan' ? 'chart' : 'settings',22)}</div><h3>${label || 'Ruang kerja sedang disiapkan'}</h3><p>Modul ini disiapkan sebagai titik integrasi berikutnya. Prototype tidak mengklaim fitur backend atau laporan sudah aktif.</p><button class="btn" data-action="navigate" data-route="dashboard">${icon('left',14)} Kembali ke ringkasan</button></div>`; }

function renderAdminPage() { switch (routeKey()) { case 'dashboard': return dashboardPage(); case 'activities': return activitiesPage(); case 'students': return studentsPage(); case 'teachers': return teachersPage(); case 'classes': return classesPage(); case 'attendance': return attendancePage(); case 'tasks': return tasksPage(); case 'spmb': return spmbPage(); case 'applicants': return applicantsPage(); case 'verification': return applicantsPage('pending'); case 'status': return statusLookupAdmin(); case 'users': return usersPage(); case 'roles': return rolesPage(); case 'reports': return placeholderPage('Laporan', 'Ringkasan operasional dan akademik dalam format yang siap diekspor.', 'Pusat laporan belum diaktifkan'); case 'school-settings': return placeholderPage('Pengaturan sekolah', 'Kelola profil sekolah, periode akademik, dan konfigurasi SPMB.', 'Pengaturan sekolah belum diaktifkan'); default: return dashboardPage(); } }

function publicNav() { return `<nav class="public-nav"><a class="brand" href="#/register"><span class="brand-mark">${icon('book',21)}</span><span class="brand-copy"><span class="brand-name">SekolahMu</span><span class="brand-sub">Penerimaan murid baru</span></span></a><div class="public-nav-actions"><button class="btn btn-ghost" data-action="navigate" data-route="check-status">Cek status pendaftaran</button><button class="btn btn-primary" data-action="start-registration">Daftar sekarang ${icon('arrow',13)}</button></div></nav>`; }
function publicHomeHero() { return `<div class="public-hero"><div><span class="data-demo">Pendaftaran demo · ${school.spmbPeriod}</span><h1>Mulai langkah baru bersama ${school.shortName}.</h1><p>Lengkapi formulir pendaftaran murid baru secara bertahap. Data pada halaman ini hanya simulasi frontend dan belum dikirim ke server sekolah.</p><div class="head-actions" style="margin-top:22px"><button class="btn btn-primary" data-action="start-registration">Mulai pendaftaran ${icon('arrow',14)}</button><button class="btn" data-action="navigate" data-route="check-status">Saya sudah mendaftar</button></div></div><div class="hero-panel"><span class="eyebrow" style="color:#8faeff">Tentang sekolah</span><h3>Belajar, bertumbuh, berdampak.</h3><p>${school.name} menyiapkan lingkungan belajar yang inklusif, tertib, dan berorientasi masa depan.</p><div class="hero-stats"><div><strong>32</strong><span>Rombel aktif</span></div><div><strong>1.024</strong><span>Murid terdaftar</span></div><div><strong>A</strong><span>Akreditasi</span></div></div></div></div><div class="public-grid"><section class="card public-card"><p class="eyebrow">Persyaratan</p><h2 style="font-size:17px;letter-spacing:-.04em;margin:0 0 14px">Siapkan dokumen berikut</h2><div class="requirements"><div class="requirement"><span class="req-check">✓</span><span>Kartu Keluarga atau surat keterangan domisili</span></div><div class="requirement"><span class="req-check">✓</span><span>Rapor semester terakhir dari sekolah asal</span></div><div class="requirement"><span class="req-check">✓</span><span>Akta kelahiran calon murid</span></div><div class="requirement"><span class="req-check">✓</span><span>Dokumen tambahan sesuai jalur pendaftaran</span></div></div></section><section class="card public-card"><p class="eyebrow">Informasi penting</p><h2 style="font-size:17px;letter-spacing:-.04em;margin:0 0 14px">Periode dan jalur</h2><div class="detail-list"><div class="detail-item"><label>Periode demo</label><strong>${school.spmbPeriod}</strong></div><div class="detail-item"><label>Jalur tersedia</label><strong>Zonasi, Prestasi, Afirmasi</strong></div><div class="detail-item"><label>Lokasi</label><strong>${school.location}</strong></div><div class="detail-item"><label>Kontak panitia</label><strong>(022) 555-0188</strong></div></div></section></div>`; }
function publicRegister() { const p = ui.public; if (p.submitted) return `<div class="public-form-wrap"><div class="card registration-card"><div class="success-state"><div class="success-mark">✓</div><p class="eyebrow">Simulasi berhasil</p><h2>Formulir demo sudah dikirim.</h2><p>Nomor pendaftaran ini dibuat di browser untuk menguji alur pemeriksaan status. Belum ada data yang dikirim ke server sekolah.</p><div class="application-code">${p.submitted}</div><div class="head-actions" style="justify-content:center"><button class="btn btn-primary" data-action="navigate" data-route="check-status">Periksa status</button><button class="btn" data-action="public-reset">Buat simulasi baru</button></div></div></div></div>`; const steps = ['Data pribadi','Sekolah asal','Jalur','Dokumen','Pemeriksaan akhir']; const fields = p.fields; return `<div class="public-form-wrap"><div style="text-align:center;margin-bottom:10px"><span class="data-demo">Formulir pendaftaran · Mode simulasi</span><h1 class="page-title" style="margin-top:12px">Pendaftaran murid baru</h1><p class="page-desc">Lengkapi data secara bertahap. Anda dapat kembali ke tahap sebelumnya tanpa kehilangan input.</p></div><div class="steps">${steps.map((s,i)=>`<div class="step ${p.step === i+1 ? 'active' : ''} ${p.step > i+1 ? 'done' : ''}"><div class="step-num">${p.step > i+1 ? '✓' : i+1}</div><span>${s}</span></div>`).join('')}</div><div class="card registration-card">${registrationStep(steps[p.step-1], fields)}</div></div>`; }
function registrationStep(title, f) { const step = ui.public.step; const titleCopy = ['Biodata calon murid dan orang tua/wali.', 'Informasi pendidikan terakhir calon murid.', 'Pilih jalur yang sesuai dengan kondisi pendaftaran.', 'Tandai dokumen yang akan diperiksa oleh panitia.', 'Tinjau kembali data sebelum simulasi dikirim.'][step-1]; let body = ''; if (step === 1) body = `<div class="form-grid">${modalFormField('Nama lengkap calon murid','name',f.name)}${modalFormField('Nomor WhatsApp orang tua/wali','phone',f.phone,'true','tel')}<div class="field"><label>Jenis kelamin <em>*</em></label><select class="form-control" name="gender" required><option value="">Pilih jenis kelamin</option>${statusOptions(['Laki-laki','Perempuan'],f.gender)}</select></div>${modalFormField('Email orang tua/wali','email',f.email,'true','email')}<div class="field full"><label>Alamat domisili <em>*</em></label><textarea class="form-control" name="address" required>${escapeHtml(f.address || '')}</textarea></div></div>`; if (step === 2) body = `<div class="form-grid">${modalFormField('Nama sekolah asal','school',f.school)}${modalFormField('Tahun lulus','graduationYear',f.graduationYear || '2026','true','number')}<div class="field"><label>Kota sekolah asal <em>*</em></label><input class="form-control" name="schoolCity" value="${escapeHtml(f.schoolCity || '')}" required /></div><div class="field"><label>Nilai rata-rata rapor <em>*</em></label><input class="form-control" name="score" type="number" step="0.01" min="0" max="100" value="${escapeHtml(f.score || '')}" required /></div></div>`; if (step === 3) body = `<div class="field"><label>Jalur pendaftaran <em>*</em></label><select class="form-control" name="path" required><option value="">Pilih jalur</option>${statusOptions(['Zonasi','Prestasi','Afirmasi'],f.path)}</select></div><div class="notice" style="margin-top:15px;margin-bottom:0">${icon('info',14)} Jalur pada prototype hanya memengaruhi data demo dan belum memvalidasi zonasi atau dokumen prestasi di server.</div>`; if (step === 4) body = `<div class="requirements"><label class="requirement" style="cursor:pointer"><input type="checkbox" name="kartuKeluarga" ${f.kartuKeluarga ? 'checked' : ''} /> <span>Kartu Keluarga siap diperiksa</span></label><label class="requirement" style="cursor:pointer"><input type="checkbox" name="rapor" ${f.rapor ? 'checked' : ''} /> <span>Rapor semester terakhir siap diperiksa</span></label><label class="requirement" style="cursor:pointer"><input type="checkbox" name="akta" ${f.akta ? 'checked' : ''} /> <span>Akta kelahiran siap diperiksa</span></label></div><div class="notice" style="margin-top:18px;margin-bottom:0">${icon('info',14)} Upload file nyata belum aktif pada prototype. Checklist di atas hanya mensimulasikan kesiapan dokumen.</div>`; if (step === 5) body = `<div class="review-box"><h4>Identitas calon murid</h4><div class="review-row"><span>Nama lengkap</span><strong>${escapeHtml(f.name || '—')}</strong></div><div class="review-row"><span>Kontak wali</span><strong>${escapeHtml(f.phone || '—')}</strong></div><div class="review-row"><span>Email</span><strong>${escapeHtml(f.email || '—')}</strong></div></div><div class="review-box"><h4>Sekolah dan jalur</h4><div class="review-row"><span>Sekolah asal</span><strong>${escapeHtml(f.school || '—')}</strong></div><div class="review-row"><span>Jalur</span><strong>${escapeHtml(f.path || '—')}</strong></div><div class="review-row"><span>Dokumen dicentang</span><strong>${['kartuKeluarga','rapor','akta'].filter(k=>f[k]).length}/3 siap diperiksa</strong></div></div><label class="requirement"><input type="checkbox" name="consent" ${f.consent ? 'checked' : ''} required /> <span>Saya memahami ini adalah simulasi frontend dan menyetujui data demo dipakai untuk menguji alur.</span></label>`; return `<p class="eyebrow">Tahap ${step} dari 5</p><h2>${title}</h2><p>${titleCopy}</p><form data-form="public-register" data-step="${step}">${body}<div class="form-actions"><button type="button" class="btn ${step === 1 ? 'btn-ghost' : ''}" data-action="register-back" ${step === 1 ? 'disabled' : ''}>${icon('left',13)} Kembali</button><button class="btn btn-primary">${step === 5 ? 'Kirim simulasi' : 'Lanjut ke tahap berikutnya'} ${icon(step === 5 ? 'check' : 'right',13)}</button></div></form>`; }
function publicStatus() { const result = ui.public.statusResult; return `<div class="public-form-wrap" style="max-width:700px"><div style="text-align:center;margin-bottom:22px"><span class="data-demo">Pelacakan demo</span><h1 class="page-title" style="margin-top:12px">Cek status pendaftaran</h1><p class="page-desc">Masukkan nomor pendaftaran yang didapat setelah simulasi pengiriman formulir.</p></div><div class="card registration-card"><form data-form="status-check"><div class="field"><label>Nomor pendaftaran</label><input class="form-control" name="number" placeholder="Contoh: SPMB-26041" value="${escapeHtml(ui.public.statusQuery || '')}" required /></div><div class="form-actions"><button class="btn btn-primary">${icon('search',14)} Periksa status</button></div></form>${result ? `<div style="margin-top:24px;padding-top:20px;border-top:1px solid var(--line)"><div class="detail-banner"><div><strong>${escapeHtml(result.name)}</strong><span>${result.id} · ${result.school}</span></div>${badge(result.status)}</div><div class="detail-list"><div class="detail-item"><label>Jalur</label><strong>${result.path}</strong></div><div class="detail-item"><label>Tanggal pendaftaran</label><strong>${dateLabel(result.date)}</strong></div><div class="detail-item"><label>Periode</label><strong>${school.spmbPeriod}</strong></div><div class="detail-item"><label>Catatan</label><strong>${escapeHtml(result.note || 'Belum ada catatan tambahan.')}</strong></div></div><div class="notice" style="margin-top:18px;margin-bottom:0">${icon('info',14)} Status pada halaman ini adalah data demo lokal. Untuk aplikasi sungguhan, hasil akan berasal dari endpoint Laravel terautentikasi.</div></div>` : ''}</div><div style="text-align:center;margin-top:16px"><button class="btn btn-ghost" data-action="navigate" data-route="register">Belum mendaftar? Mulai di sini ${icon('arrow',13)}</button></div></div>`; }
function renderPublic() { const content = routeKey() === 'register' ? (location.hash === '#/register' && ui.public.step === 0 ? publicHomeHero() : publicRegister()) : publicStatus(); if (routeKey() === 'register' && ui.public.step === 0) return `<div class="public-shell">${publicNav()}<main class="public-main">${publicHomeHero()}</main></div>`; return `<div class="public-shell">${publicNav()}<main class="public-main">${content}</main></div>`; }

function confirmModal(title, message, onConfirm, confirmLabel = 'Ya, lanjutkan', danger = false) { ui.modal = { html: modal(title, 'Periksa kembali tindakan ini sebelum melanjutkan.', `<div class="confirm-copy"><div class="confirm-icon">${icon(danger ? 'trash' : 'info',22)}</div><h4>${title}</h4><p>${message}</p><div class="form-actions" style="justify-content:center;margin-top:20px"><button class="btn" data-action="close-modal">Batal</button><button class="btn ${danger ? 'btn-danger' : 'btn-primary'}" data-action="confirm-modal">${confirmLabel}</button></div></div>`), onConfirm }; render(); }
function entityForm(entity, id) { const state = store.get(); const existing = id ? state[`${entity}s`]?.find(x => x.id === id) : null; const title = existing ? `Edit ${entityLabel(entity)}` : `Tambah ${entityLabel(entity)}`; let body = ''; if (entity === 'student') body = `<form data-form="student" data-id="${id || ''}"><div class="form-grid">${modalFormField('Nama lengkap','name',existing?.name || '')}${modalFormField('Nomor WhatsApp','phone',existing?.phone || '','false','tel')}<div class="field"><label>Jenis kelamin <em>*</em></label><select class="form-control" name="gender" required>${statusOptions(['Laki-laki','Perempuan'],existing?.gender)}</select></div><div class="field"><label>Kelas <em>*</em></label><select class="form-control" name="className" required>${state.classes.map(c=>`<option ${existing?.className===c.name?'selected':''}>${c.name}</option>`).join('')}</select></div></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary">Simpan data</button></div></form>`; if (entity === 'teacher') body = `<form data-form="teacher" data-id="${id || ''}"><div class="form-grid">${modalFormField('Nama lengkap','name',existing?.name || '')}${modalFormField('Email demo','email',existing?.email || '','true','email')}${modalFormField('Mata pelajaran','subject',existing?.subject || '')}${modalFormField('Kelas yang diampu','classes',existing?.classes || '')}</div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary">Simpan data</button></div></form>`; if (entity === 'class') body = `<form data-form="class" data-id="${id || ''}"><div class="form-grid">${modalFormField('Nama kelas','name',existing?.name || '')}${modalFormField('Tingkat','level',existing?.level || '')}${modalFormField('Wali kelas','homeroom',existing?.homeroom || '')}${modalFormField('Kapasitas','capacity',existing?.capacity || 32,'true','number')}</div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary">Simpan data</button></div></form>`; if (entity === 'task') body = `<form data-form="task" data-id="${id || ''}"><div class="form-grid">${modalFormField('Judul tugas','title',existing?.title || '')}<div class="field"><label>Kelas <em>*</em></label><select class="form-control" name="className" required>${state.classes.map(c=>`<option ${existing?.className===c.name?'selected':''}>${c.name}</option>`).join('')}</select></div><div class="field full"><label>Deskripsi <em>*</em></label><textarea class="form-control" name="description" required>${escapeHtml(existing?.description || '')}</textarea></div>${modalFormField('Guru pembuat','teacher',existing?.teacher || '')}${modalFormField('Tenggat waktu','due',existing?.due || today,'true','date')}<div class="field"><label>Prioritas <em>*</em></label><select class="form-control" name="priority" required>${statusOptions(['Rendah','Normal','Tinggi'],existing?.priority || 'Normal')}</select></div></div><div class="form-actions"><button type="button" class="btn" data-action="close-modal">Batal</button><button class="btn btn-primary">Simpan tugas</button></div></form>`; return modal(title, existing ? 'Perubahan akan memperbarui data demo lintas halaman.' : 'Isi informasi utama. Data akan tersimpan lokal di browser.', body, true); }
function entityLabel(entity) { return ({ student:'murid', teacher:'guru', class:'kelas', task:'tugas' })[entity] || entity; }
function applicantDetail(id) { const a = store.get().applicants.find(x=>x.id===id); if (!a) return ''; const next = a.status === 'Menunggu Verifikasi' ? 'Sedang Diverifikasi' : a.status === 'Sedang Diverifikasi' ? 'Terverifikasi' : null; const actions = next ? `<button class="btn btn-primary" data-action="advance-applicant" data-id="${a.id}" data-status="${next}">${icon('check',13)} ${next}</button>` : a.status === 'Terverifikasi' ? `<button class="btn btn-primary" data-action="advance-applicant" data-id="${a.id}" data-status="Diterima">${icon('check',13)} Tandai diterima</button><button class="btn btn-danger" data-action="advance-applicant" data-id="${a.id}" data-status="Ditolak">Tolak pendaftaran</button>` : ''; return modal('Detail pendaftar', `${a.id} · Data sintetis untuk simulasi pemeriksaan`, `<div class="detail-banner"><div>${initialsCell(a.name, `${a.gender} · ${a.phone}`)}</div>${badge(a.status)}</div><div class="section-label">Identitas dan sekolah asal</div><div class="detail-list" style="margin-bottom:20px"><div class="detail-item"><label>Nama lengkap</label><strong>${escapeHtml(a.name)}</strong></div><div class="detail-item"><label>Asal sekolah</label><strong>${escapeHtml(a.school)}</strong></div><div class="detail-item"><label>Jalur pendaftaran</label><strong>${escapeHtml(a.path)}</strong></div><div class="detail-item"><label>Tanggal daftar</label><strong>${dateLabel(a.date)}</strong></div></div><div class="section-label">Dokumen persyaratan</div><div class="list" style="border:1px solid var(--line);border-radius:9px;margin-bottom:20px">${Object.entries(a.documents || {}).map(([k,v])=>`<div class="list-row"><div class="list-main"><strong>${k === 'kartuKeluarga' ? 'Kartu Keluarga' : k === 'rapor' ? 'Rapor semester terakhir' : 'Akta kelahiran'}</strong></div><div>${badge(v)}</div></div>`).join('')}</div><div class="section-label">Riwayat status</div><div class="timeline" style="padding:0 0 4px">${(a.history || []).slice().reverse().map(h=>`<div class="timeline-item"><span class="timeline-dot"></span><div class="timeline-copy"><strong>${h.status}</strong><p>${h.date} · ${h.by}</p></div></div>`).join('')}</div><div class="form-actions">${actions || '<span style="font-size:10px;color:var(--muted);margin-right:auto">Status akhir simulasi sudah tercapai.</span>'}<button class="btn" data-action="close-modal">Tutup</button></div>`, true); }

function render() { if (isPublic()) { app.innerHTML = renderPublic(); return; } app.innerHTML = adminShell(renderAdminPage()); }

// Global interactions: a small event surface keeps the prototype easy to replace with API calls.
document.addEventListener('click', event => {
  const target = event.target.closest('[data-action]'); if (!target) return;
  const action = target.dataset.action;
  if (action === 'start-registration') { event.preventDefault(); ui.public.step = 1; render(); }
  else if (action === 'navigate') { event.preventDefault(); ui.sidebarOpen = false; if (target.dataset.route === 'register' && routeKey() === 'register') { ui.public.step = 1; render(); } else { if (target.dataset.route === 'register') ui.public.step = 0; go(target.dataset.route); } }
  else if (action === 'toggle-sidebar') { ui.sidebarOpen = !ui.sidebarOpen; render(); }
  else if (action === 'close-modal') { if (event.target.closest('[data-modal-content]') && target === event.target) return; ui.modal = null; render(); }
  else if (action === 'confirm-modal') { const callback = ui.modal?.onConfirm; ui.modal = null; render(); callback?.(); }
  else if (action === 'page') { const page = Number(target.dataset.page); if (page > 0) { setPage(target.dataset.pageKey, page); render(); } }
  else if (action === 'new-student') { ui.modal = { html: entityForm('student') }; render(); }
  else if (action === 'new-teacher') { ui.modal = { html: entityForm('teacher') }; render(); }
  else if (action === 'new-class') { ui.modal = { html: entityForm('class') }; render(); }
  else if (action === 'new-task') { ui.modal = { html: entityForm('task') }; render(); }
  else if (action.startsWith('edit-')) { const entity = action.slice(5); ui.modal = { html: entityForm(entity, target.dataset.id) }; render(); }
  else if (action.startsWith('delete-')) { const entity = action.slice(7); confirmModal(`Hapus ${entityLabel(entity)}?`, 'Tindakan ini hanya menghapus data dari penyimpanan demo browser dan tidak dapat dibatalkan setelah dikonfirmasi.', () => { const methods = { student:'removeStudent', teacher:'removeTeacher', class:'removeClass', task:'removeTask' }; store[methods[entity]]?.(target.dataset.id); toast('Data dihapus', 'Perubahan tersimpan pada demo lokal.'); }, 'Ya, hapus data', true); }
  else if (action.startsWith('view-')) { const entity = action.slice(5); if (entity === 'applicant') { ui.modal = { html: applicantDetail(target.dataset.id) }; render(); } }
  else if (action === 'advance-applicant') { const item = store.get().applicants.find(x=>x.id===target.dataset.id); confirmModal(`Ubah status menjadi ${target.dataset.status}?`, `${item?.name || 'Pendaftar'} akan berpindah ke tahap ${target.dataset.status}. Perubahan ini akan tercatat pada riwayat demo.`, () => { store.updateApplicantStatus(target.dataset.id, target.dataset.status); toast('Status diperbarui', `${item?.name || 'Pendaftar'} sekarang ${target.dataset.status}.`); }, 'Ya, ubah status'); }
  else if (action === 'mark-all-present') { const f = stateFor('attendance'); const className = f.className || store.get().classes[0].name; const date = f.date || today; ui.attDraft = Object.fromEntries(store.get().students.filter(s=>s.className===className).map(s=>[s.id,'Hadir'])); ui.attDirty = true; render(); }
  else if (action === 'save-attendance') { if (!ui.attDirty) return; const f = stateFor('attendance'); const className = f.className || store.get().classes[0].name; const date = f.date || today; store.saveAttendance(date, className, ui.attDraft); ui.attDirty = false; toast('Absensi tersimpan', `Rekap ${className} pada ${dateLabel(date)} telah diperbarui.`); render(); }
  else if (action === 'export-attendance') { exportAttendance(); }
  else if (action === 'reset-demo') { confirmModal('Reset data demo?', 'Semua perubahan lokal akan dikembalikan ke data sintetis awal.', () => { store.reset(); ui.filters = {}; ui.pages = {}; toast('Data demo direset', 'Seluruh modul kembali ke kondisi awal.'); }, 'Ya, reset data'); }
  else if (action === 'show-notification') { toast('Tidak ada notifikasi baru', 'Semua aktivitas penting sudah ditinjau.'); }
  else if (action === 'register-back') { ui.public.step = Math.max(1, ui.public.step - 1); render(); }
  else if (action === 'public-reset') { ui.public = { step: 1, fields: {}, submitted: null, statusQuery: '', statusResult: null }; render(); }
});

document.addEventListener('keydown', event => { if (event.key === 'Escape' && ui.modal) { ui.modal = null; render(); } if (event.key === 'Enter' && event.target.matches('[data-table-search]')) { const key = event.target.dataset.tableSearch; ui.filters[key] = { ...(ui.filters[key] || {}), query: event.target.value }; setPage(key === 'applicants' ? 'applicants-all' : key, 1); render(); } if (event.key === 'Enter' && event.target.matches('[data-top-search]')) { const value = event.target.value.toLowerCase(); const route = value.includes('tugas') ? 'tasks' : value.includes('guru') ? 'teachers' : value.includes('murid') ? 'students' : value.includes('spmb') || value.includes('daftar') ? 'applicants' : 'dashboard'; go(route); } });

document.addEventListener('change', event => {
  const target = event.target;
  if (target.matches('[data-filter-select]')) { const [key, field] = target.dataset.filterSelect.split('.'); ui.filters[key] = { ...(ui.filters[key] || {}), [field]: target.value }; setPage(key === 'applicants' ? 'applicants-all' : key, 1); if (key === 'attendance') { ui.attDraft = store.getAttendance(ui.filters[key].date || today, ui.filters[key].className || store.get().classes[0].name); ui.attDirty = false; } render(); }
  if (target.matches('[data-filter-input]')) { const [key, field] = target.dataset.filterInput.split('.'); ui.filters[key] = { ...(ui.filters[key] || {}), [field]: target.value }; if (key === 'attendance') { ui.attDraft = store.getAttendance(ui.filters[key].date || today, ui.filters[key].className || store.get().classes[0].name); ui.attDirty = false; } render(); }
  if (target.matches('[data-att-status]')) { ui.attDraft = { ...(ui.attDraft || {}), [target.dataset.attStatus]: target.value }; ui.attDirty = true; render(); }
});

document.addEventListener('submit', event => {
  event.preventDefault(); const form = event.target; const fd = Object.fromEntries(new FormData(form));
  if (form.dataset.form === 'student' || form.dataset.form === 'teacher' || form.dataset.form === 'class' || form.dataset.form === 'task') { const entity = form.dataset.form, id = form.dataset.id; ui.modal = null; if (entity === 'student') id ? store.updateStudent(id, fd) : store.addStudent(fd); if (entity === 'teacher') id ? store.updateTeacher(id, fd) : store.addTeacher(fd); if (entity === 'class') id ? store.updateClass(id, fd) : store.addClass(fd); if (entity === 'task') id ? store.updateTask(id, fd) : store.addTask(fd); toast(`${entityLabel(entity)} berhasil disimpan`, 'Data demo diperbarui lintas halaman.'); render(); }
  if (form.dataset.form === 'public-register') { Object.entries(fd).forEach(([key,value]) => { ui.public.fields[key] = form.querySelector(`[name="${key}"]`)?.type === 'checkbox' ? true : value; }); const step = Number(form.dataset.step); if (step < 5) { ui.public.step = step + 1; render(); } else { if (!ui.public.fields.consent) { toast('Persetujuan diperlukan', 'Centang persetujuan simulasi sebelum mengirim.', true); return; } const code = `SPMB-26${String(store.get().applicants.length + 42).padStart(3,'0')}`; store.addApplicant({ id: code, name: ui.public.fields.name, school: ui.public.fields.school, path: ui.public.fields.path, date: today, phone: ui.public.fields.phone, gender: ui.public.fields.gender, note: 'Masuk dari formulir publik demo.' }); ui.public.submitted = code; render(); toast('Simulasi berhasil dikirim', `Nomor pendaftaran ${code} dibuat di browser.`); } }
  if (form.dataset.form === 'status-check') { ui.public.statusQuery = fd.number; ui.public.statusResult = store.get().applicants.find(a => a.id.toLowerCase() === String(fd.number).toLowerCase()) || null; render(); if (!ui.public.statusResult) toast('Nomor belum ditemukan', 'Gunakan nomor pendaftaran demo yang tersedia.', true); }
  if (form.dataset.form === 'admin-status') { ui.adminStatusQuery = fd.number; ui.adminStatusResult = store.get().applicants.find(a => a.id.toLowerCase() === String(fd.number).toLowerCase()) || null; render(); if (!ui.adminStatusResult) toast('Nomor belum ditemukan', 'Periksa kembali nomor pendaftaran demo.', true); }
});

document.addEventListener('input', event => { if (event.target.matches('[data-top-search]')) ui.topQuery = event.target.value; });

function exportAttendance() { const f = stateFor('attendance'), className = f.className || store.get().classes[0].name, date = f.date || today, records = ui.attDraft || store.getAttendance(date, className), rows = [['Nomor induk','Nama','Kelas','Tanggal','Status'], ...store.get().students.filter(s=>s.className===className).map(s=>[s.id,s.name,className,date,records[s.id] || 'Hadir'])]; const csv = rows.map(row => row.map(cell => `"${String(cell).replaceAll('"','""')}"`).join(',')).join('\n'); const blob = new Blob([csv], { type:'text/csv;charset=utf-8;' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = `absensi-${className.replaceAll(' ','-')}-${date}.csv`; link.click(); URL.revokeObjectURL(url); toast('CSV dibuat', 'File rekap absensi demo sudah diunduh.'); }

window.addEventListener('hashchange', () => { if (!isPublic()) { ui.public.step = 0; } render(); window.scrollTo({ top: 0, behavior: 'smooth' }); });
store.subscribe(() => { if (!isPublic()) render(); });
if (location.hash === '#/register') ui.public.step = 0;
render();
